PARTS = {"A": ["F-1","F-2","F-3","F-5","F-6","F-7","F-8","F-9","F-14","F-18","F-19","F-20","F-30"],
         "B": ["F-10","F-12","F-13","F-22","F-34","F-35","F-36","F-37","F-38","F-41"],
         "C": ["F-11","F-21","F-31","F-39","F-40","F-43"],
         "D": ["F-32","F-33","F-42","M-3","M-4"],
         "E": ["F-4","F-15","F-16","F-17","M-1","M-2"]}

def render(part, intro=""):
    out = [f"## Part {part}", "", intro, ""] if intro else [f"## Part {part}", ""]
    for k in PARTS[part]:
        if k not in E: out.append(f"### {k}\n\n(not yet written)\n"); continue
        e = E[k]
        out += [f"### {k}: **{e['cls']}** — {e['clause']}", "", f"Basis: {e['basis']}. Files: " + "; ".join(f"`{f}`" for f in e["files"]) + ".", "", e["text"], ""]
    return "\n".join(out)

if __name__ == "__main__":
    old = json.load(open(OUT)) if os.path.exists(OUT) else {}
    old.update(E); json.dump(old, open(OUT, "w"), indent=1)
    print(len(old), "entries in", OUT)
